import {renderCowRecovery} from './cow-recovery-ui.js';
import {renderCowUpgrades} from './cow-upgrade-ui.js';
import {t} from './locales.js';import {COW} from './cow-config.js';import {FEATURES} from './features.js';import {cowFeedBuyReason} from './cow-feed.js';
/** Presentation-only double-gesture guard; never advances the game or creates inventory. */
let pendingFeed=false;let refresh=()=>{};
/** @param {import('./engine.js').State} state @param {import('./cow-panel.js').CowSend} send @param {HTMLElement} host */
export function renderCowShop(state,send,host){const g=state.cow;if(!FEATURES.cow||!g?.visited)return;const section=document.createElement('section');section.id='cow-shop';const heading=document.createElement('h3');heading.textContent=t('cowSupplies');const stock=document.createElement('p');stock.className='market-note';stock.textContent=t('cowPaidFeed')+': '+g.feedStoreG/1000+' / '+COW.feedStoreMaxG/1000+' kg';const button=document.createElement('button'),note=document.createElement('p'),reason=cowFeedBuyReason(state);button.id='buy-cow-feed';button.type='button';button.className='action-button';button.textContent=t('cowBuyFeed')+' · '+COW.feedBagG/1000+' kg / '+COW.feedBagPrice+' '+t('coins');note.id='buy-cow-feed-reason';note.className='market-note';note.textContent=reason?t(reason):t('cowFeedBagHelp');button.setAttribute('aria-describedby',note.id);button.addEventListener('click',event=>{if(button.disabled||pendingFeed||event.detail>1)return;pendingFeed=true;refresh();const finish=()=>setTimeout(()=>{pendingFeed=false;refresh();},300);Promise.resolve(send('buyCowFeed')).then(finish,finish);});section.append(heading,stock,button,note);host.append(section);renderCowUpgrades(state,send,host);renderCowRecovery(state,send,host);refresh=()=>{button.disabled=pendingFeed||!!reason;};refresh();}
